// Server-side checks. Nothing is stored or emailed unless every field is valid.
const s = $input.first().json;
const fail = (error) => [{ json: { valid: false, error } }];
const line = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const EMAIL = /^[^\s@<>",;]+@[^\s@<>",;]+\.[^\s@<>",;]+$/;
const name = line(s['Your Name']);
const requester = line(s['Your Email']).toLowerCase();
const approver = line(s['Approver Email']).toLowerCase();
const title = line(s['What Needs Approval']);
const details = String(s['Details'] ?? '').replace(/\r\n?/g, '\n').trim();
if (!name) return fail('Please enter your name.');
if (name.length > 100) return fail('Please keep your name under 100 characters.');
if (!EMAIL.test(requester)) return fail('Please enter a valid email address for yourself.');
if (!EMAIL.test(approver)) return fail('Please enter a valid email address for the approver.');
if (approver === requester) return fail('You cannot approve your own request. Please enter someone else as the approver.');
if (!title) return fail('Please describe what needs approval.');
if (title.length > 150) return fail('Please keep "What Needs Approval" under 150 characters and put the rest in Details.');
if (details.length > 3000) return fail('Please keep Details under 3000 characters.');
const remind = Number(s.remind_after_hours), expire = Number(s.expire_after_hours);
if (!(expire > 0) || !(remind > 0) || remind >= expire) return fail('Setup problem: remind_after_hours and expire_after_hours must be above 0, with the reminder first. Nothing was sent.');
if (!/^https?:\/\/[^\s"<>]+$/.test(String(s.decision_page_url ?? ''))) return fail('Setup problem: decision_page_url must be the Production URL of Decision Link Opened. Nothing was sent.');
return [{ json: { valid: true, name, requester, approver, title, details, remind, expire } }];

// Read the token and the button the approver clicked from the link. A malformed token is treated as unknown.
const q = $('Decision Link Opened').first().json.query || {};
const token = String(q.token ?? '').trim().toLowerCase();
const choice = String(q.decision ?? '').trim().toLowerCase();
return [{ json: { token: /^[0-9a-f]{64}$/.test(token) ? token : '', choice: ['approve', 'reject'].includes(choice) ? choice : '' } }];

// Opening a link never decides anything: it only shows this page. The decision is recorded when the button POSTs the form.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const page = (heading, body, code, org = '') => [{ json: { code, html: '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">'
  + '<title>' + esc(heading) + '</title><style>body{font-family:system-ui,sans-serif;background:#f4f5f7;margin:0;padding:24px;color:#222}main{max-width:560px;margin:40px auto;background:#fff;border-radius:8px;padding:28px;box-shadow:0 1px 4px rgba(0,0,0,.1)}'
  + 'h1{font-size:22px;margin-top:0}.muted{color:#666;font-size:14px}textarea{width:100%;box-sizing:border-box;min-height:80px;margin:8px 0 16px}button{font-size:16px;padding:10px 20px;border:0;border-radius:6px;cursor:pointer;margin-right:8px}.approve{background:#1f7a3d;color:#fff}.reject{background:#b42318;color:#fff}.box{background:#f8f8f8;padding:12px;border-radius:6px;white-space:pre-wrap}</style></head>'
  + '<body><main><p class="muted">' + esc(org) + '</p><h1>' + esc(heading) + '</h1>' + body + '</main></body></html>' } }];
const request = (r) => '<p><b>' + esc(r.title) + '</b><br><span class="muted">Requested by ' + esc(r.requester_name) + ' (' + esc(r.requester_email) + ')</span></p>' + (r.details ? '<div class="box">' + esc(r.details) + '</div>' : '');
const decided = (r) => page('This request was already ' + r.status, request(r) + '<p>It was ' + esc(r.status) + ' on ' + esc(r.decided_label) + '. Nothing was changed.</p>', 409, r.organization_name);
const expired = (r) => page('This request has expired', request(r) + '<p>It expired on ' + esc(r.expires_label) + ' without a decision. Nothing was changed. Ask the requester to submit it again if it is still needed.</p>', 410, r.organization_name);
const missing = () => page('This link is not valid', '<p>The link is incomplete or the request does not exist. Open the link from the original email, without changing it.</p>', 404);
const r = $input.first().json;
const choice = $('Check Link').first().json.choice;
if (r.outcome === 'already_decided') return decided(r);
if (r.outcome === 'expired') return expired(r);
if (r.outcome !== 'pending') return missing();
const approve = '<button class="approve" type="submit" name="decision" value="approve">Approve</button>';
const reject = '<button class="reject" type="submit" name="decision" value="reject">Reject</button>';
return page(choice === 'reject' ? 'Reject this request?' : choice === 'approve' ? 'Approve this request?' : 'Approve or reject this request?',
  request(r)
  + '<form method="post"><input type="hidden" name="token" value="' + esc($('Check Link').first().json.token) + '">'
  + '<label for="comment">Comment for the requester (optional)</label><textarea id="comment" name="comment" maxlength="1000"></textarea>'
  + (choice === 'reject' ? reject + approve : approve + reject) + '</form>'
  + '<p class="muted">Nothing is recorded until you press a button. This request expires on ' + esc(r.expires_label) + '.</p>', 200, r.organization_name);

// Read the confirmation form. The decision comes only from the button pressed (POST body), never from the link.
const b = $('Decision Submitted').first().json.body || {};
const token = String(b.token ?? '').trim().toLowerCase();
const decision = { approve: 'approved', reject: 'rejected' }[String(b.decision ?? '').trim().toLowerCase()] || 'invalid';
const comment = String(b.comment ?? '').replace(/\r\n?/g, '\n').trim().slice(0, 1000);
return [{ json: { token: /^[0-9a-f]{64}$/.test(token) ? token : '', decision, comment } }];

