const r = $('Record Decision').first().json;
if (r.outcome === 'already_decided') return decided(r);
if (r.outcome === 'expired') return expired(r);
if (r.outcome === 'invalid') return page('Please choose Approve or Reject', '<p>No decision was recorded. Go back and press one of the two buttons.</p>', 400, r.organization_name);
if (r.outcome !== 'recorded') return missing();
const emailFailed = $('Save Decision Email Error').isExecuted;
return page('Request ' + r.status, request(r)
  + (r.decision_comment ? '<p>Your comment:</p><div class="box">' + esc(r.decision_comment) + '</div>' : '')
  + '<p>Your decision was recorded on ' + esc(r.decided_label) + '. '
  + (emailFailed ? 'We could not email ' + esc(r.requester_email) + ', so please let them know yourself.' : esc(r.requester_name) + ' has been emailed.') + '</p>', 200, r.organization_name);
